-- 0024: 兩件事——
--   ① skills_detail 整包同步成 repo 版。b7421ee（2026-06-10）把四個分類的 overview 與 24 項描述
--      改寫成口語版，但只改了 repo、沒產 migration，線上至今仍是舊的正式書面版。
--      同一次整包也把 0021 原本想做的 LightGBM/XGBoost 0.6/0.4 混合敘述帶上線，
--      並把 XGBoost 移回 data_analysis 的第 3 位（0019 當初是附加在陣列尾端）。
--      ⚠️ manufacturing 的熟練度以「線上 D1」為準，不用 repo 值——本人曾用 admin 後台調整過：
--         CNC 銑床: 進階 -> 基礎、Mastercam: 熟悉 -> 基礎、AutoCAD: 熟悉 -> 進階、金屬焊接: 熟悉 -> 基礎、雷射切割: 熟悉 -> 進階
--         （線上英文版沒跟著改，這裡一併補上，讓中英文一致；repo 的 cvData 已於 2026-09-02 對齊）
--   ② vap 專案整列改寫（2026-09-12 擴大，原本只是拿掉「首個」）：
--      ・發表狀態：投稿中 -> 獲 IEEE GCCE 2026 接受（poster），badge 同步改為 Poster
--      ・病人數更正 n=109（VAP 54/非 VAP 55）-> n=107（VAP 52/非 VAP 55）——109 是論文與舊文件的錯誤
--      ・成果表改為「視窗層 vs 病人層」兩種切分的對照：原本表頭寫 Stay-level 5-fold CV，
--        底下卻是視窗層切分算出來的 0.98-0.99；病人層重跑後是 AUROC 0.61-0.67、AUPRC 0.033-0.143
--        （2026-07-13 複查，來源 newtop2to5_extended_results.csv；只有 72h 跑滿 5 fold）
--      ・拿掉三項在該評估設定下站不住的宣稱：「杜絕 Data Leakage」、「顯著優於 LR/RF/SVM」、
--        「突破 24 小時限制達成 72 小時超前預警」
--      指導教授 2026-09 的定調是「當作環境狀況過度理想化」，文案依此框架書寫。
--      驗證：2026-09-02 的全站對源確認線上 vap 與 repo 僅差一句「首個」，無 admin 手改，故可整列覆寫。
-- 冪等：整包 UPDATE 就地改值；用 UPDATE 而非 INSERT OR REPLACE，不碰 sort_order。

UPDATE sections
SET zh = '{"data_analysis":{"title":"數據分析","en":"Data Analysis","overview":"主要做生醫訊號跟臨床數據，從清資料、做特徵到訓練模型、看結果，整個流程都自己跑過。","skills":[{"name":"深度學習","level":"進階","desc":"玩過 LSTM、CNN 這類時序模型，前處理到調超參數都自己來，主要拿來做生醫訊號的序列預測。","projects":["VAP 深度學習預測系統"]},{"name":"LightGBM","level":"進階","desc":"用於 BitOGuard 的不平衡二元分類，與 XGBoost 以 0.6/0.4 加權混合，搭配 SHAP 檢視每個特徵對帳戶風險分數的貢獻，並比較不同決策閾值下的 Precision 與 Recall。","projects":["AWS x BitoPro 黑客松"]},{"name":"XGBoost","level":"熟悉","desc":"在 BitOGuard 與 LightGBM 以 0.4 權重加權混合（單獨 OOF AUC 0.827）；另用在 DSP／訊號分類課程與實驗。","projects":["AWS x BitoPro 黑客松"]},{"name":"特徵工程","level":"進階","desc":"抓時域（均值、峰值）跟頻域（FFT 功率譜）特徵；電子病歷的部分用時序聚合跟 One-Hot 編碼處理，這些醫療數據缺失率都不低。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]},{"name":"訊號過濾","level":"熟悉","desc":"帶通濾波、Z-score 標準化、缺失值補值，把生理訊號的輸入品質顧好，模型才不會對雜訊太敏感。","projects":["VAP 深度學習預測系統"]},{"name":"數據結構化","level":"熟悉","desc":"電子病歷的 ETL 清洗、用 AWS Glue 做圖形化多跳分析，把原始的非結構化資料整理成可以丟進模型訓練的特徵矩陣。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]}]},"programming":{"title":"程式開發","en":"Programming","overview":"從嵌入式韌體寫到 ML 管線都碰過，硬體這邊用 C/C++，資料跟模型那邊用 Python。","skills":[{"name":"C / C++","level":"進階","desc":"寫嵌入式韌體最常用的語言。GPIO 控制、中斷處理、記憶體管理都算熟，ChibiOS HAL 的設定（chconf / halconf / mcuconf）跟 QMK Firmware 架構也碰過，在資源有限的 STM32 上寫底層驅動沒問題。","projects":["FRC Swerve Drive 全向輪控制系統","QMK x STM32 客製鍵盤"]},{"name":"Python","level":"進階","desc":"考過 ITS Python 國際認證。平常拿來寫 ML 管線（PyTorch、scikit-learn、pandas）、畫圖（Matplotlib），也用 AWS SDK 接雲端服務。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]},{"name":"LabVIEW","level":"熟悉","desc":"用圖形化介面寫過向量合成運動學演算法跟 PID 閉迴路控制，裝在競賽機器人上即時跑，那年拿到 2022 FRC 控制創新獎。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Arduino","level":"熟悉","desc":"拿來做快速原型，接過 ESP32 無線通訊、讀感測器、控制繼電器，方便在短時間內把硬體功能跑起來驗證。","projects":["ESP32 無線打地鼠機"]},{"name":"MATLAB","level":"基礎","desc":"拿來做訊號處理分析跟演算法驗證，寫程式前先用它把濾波效果、模型邏輯畫出來確認一遍。","projects":[]}]},"eda":{"title":"電路設計","en":"Electronic Design Automation","overview":"電路圖到 PCB Layout 都自己做，用過 Altium、EasyEDA Pro、KiCAD，電源管理跟 MCU 外圍電路比較熟。","skills":[{"name":"Altium Designer","level":"進階","desc":"做多層 PCB 設計的主力工具。電源規劃、阻抗匹配、DFM（可製造性設計）原則都會考慮，原理圖到 Gerber 輸出整個流程自己一個人就能搞定。","projects":["QMK x STM32 客製鍵盤"]},{"name":"EasyEDA Pro（立創EDA）","level":"熟悉","desc":"雲端版 EDA 工具，直接接立創商城的元件庫，封裝拿來就能用，打樣也能一鍵下單。QMK 數字鍵盤的 PCB 就是用它畫的，原理圖、Layout、Gerber 匯出都包了。","projects":["QMK x STM32 數字鍵盤"]},{"name":"KiCAD","level":"熟悉","desc":"開源 EDA 工具，個人專案想快速出板就會用它，元件庫管理跟 3D 封裝預覽都用得上手，概念驗證階段很方便。","projects":[]},{"name":"OrCAD","level":"基礎","desc":"畫電路圖、跑基本的 SPICE 模擬，拿來確認被動元件選型跟電源電路的行為對不對。","projects":[]}]},"manufacturing":{"title":"機構加工","en":"Manufacturing","overview":"設計到實體都做過：CNC 銑床、3D 列印、金屬焊接、雷射切割，建模用 Inventor，刀具路徑用 Mastercam。","skills":[{"name":"CNC 銑床","level":"基礎","desc":"用 CNC 銑床做鋁合金精密加工，刀具路徑規劃跟夾具設計都會自己弄，比手工銑床穩定很多，精度跟重現性都好控制。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Mastercam","level":"基礎","desc":"CNC 加工的 CAM 軟體，把 3D 模型丟進去規劃刀具路徑（鑽孔、深孔啄鑽、2D/3D 挖槽、輪廓銑削、動態銑削、倒角），模擬沒問題再輸出 NC 程式。Swerve Drive 的全向輪鋁板跟傳動心軸就是這樣加工出來的。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"3D 列印","level":"進階","desc":"FDM 快速成型，拿來驗證機構會不會干涉，或是做一些不承重的客製零件，重量跟加工成本都能壓下來，又不影響結構強度。","projects":["FRC Swerve Drive 全向輪控制系統","ESP32 無線打地鼠機"]},{"name":"Autodesk Inventor","level":"進階","desc":"做 3D 機構建模的主力工具，組件干涉分析跟動態模擬都會跑，在實際組裝前先把零件碰撞跟公差問題抓出來。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"AutoCAD","level":"進階","desc":"畫 2D 工程圖、輸出加工圖面，把尺寸標註跟公差規格標清楚，讓 CNC 操作員或外包廠商照著做就對了。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Fusion 360","level":"熟悉","desc":"快速建概念模型，CAM 整合也在裡面，初期設計想法用它試很方便，直接從 3D 模型生成加工路徑，小批量自己做。","projects":[]},{"name":"金屬焊接","level":"基礎","desc":"MIG / TIG 基礎焊接，用在 FRC 機器人底盤的鋼管結構上，焊道均不均勻、結構夠不夠強都要顧。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"雷射切割","level":"進階","desc":"板金跟壓克力結構件的精密裁切，照著 CAD 圖面就能快速做出自訂尺寸的薄板結構跟標示面板。","projects":[]},{"name":"基礎機械加工","level":"熟悉","desc":"手工銑床、車床的基本操作，量具怎麼用、工件怎麼夾都會，這些底子讓我後來學 CNC 進階加工上手得快一點。","projects":[]}]}}',
    en = '{"data_analysis":{"title":"Data Analysis","en":"Data Analysis","overview":"Mostly working with biomedical signals and clinical data — I go through the whole loop myself, from cleaning raw data and building features to training models and checking the results.","skills":[{"name":"Deep Learning","level":"進階","desc":"I''ve worked with LSTM and CNN time-series models — preprocessing, hyperparameter tuning, all of it — mainly for predicting biomedical signal sequences.","projects":["ICU VAP Early-Warning System"]},{"name":"LightGBM","level":"進階","desc":"Used in BitOGuard for imbalanced binary classification, blended 0.6/0.4 with XGBoost, with SHAP to inspect each feature''s contribution to account-risk scores and threshold comparisons for precision and recall.","projects":["AWS × BitoPro Hackathon"]},{"name":"XGBoost","level":"熟悉","desc":"Blended with LightGBM at 0.4 weight in BitOGuard (alone: OOF AUC 0.827); also used in DSP and signal-classification coursework.","projects":["AWS × BitoPro Hackathon"]},{"name":"Feature Engineering","level":"進階","desc":"Pulled out time-domain (mean, peak) and frequency-domain (FFT power spectrum) features, and handled EHR data — time-series aggregation, one-hot encoding, plenty of missing values to deal with.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]},{"name":"Signal Filtering","level":"熟悉","desc":"Band-pass filtering, Z-score normalization, missing-value imputation — basically cleaning up physiological signals so the model isn''t thrown off by noise.","projects":["ICU VAP Early-Warning System"]},{"name":"Data Structuring","level":"熟悉","desc":"EHR ETL cleaning and AWS Glue graph-based multi-hop analysis — turning messy unstructured data into feature matrices the model can actually train on.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]}]},"programming":{"title":"Programming","en":"Programming","overview":"I''ve touched everything from embedded firmware to ML pipelines — C/C++ for the hardware side, Python for data and models.","skills":[{"name":"C / C++","level":"進階","desc":"My go-to language for embedded firmware. Comfortable with GPIO control, interrupt handling, and memory management; also worked with ChibiOS HAL config (chconf/halconf/mcuconf) and the QMK firmware codebase on resource-constrained STM32 boards.","projects":["FRC Swerve Drive Research","QMK × STM32 Custom Numpad"]},{"name":"Python","level":"進階","desc":"Hold the ITS Python international certification. Use it daily for ML pipelines (PyTorch, scikit-learn, pandas), plotting (Matplotlib), and wiring up AWS services with the SDK.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]},{"name":"LabVIEW","level":"熟悉","desc":"Used graphical programming to build vector-composition kinematics and PID closed-loop control, running live on a competition robot — that project won the 2022 FRC Innovation in Control Award.","projects":["FRC Swerve Drive Research"]},{"name":"Arduino","level":"熟悉","desc":"My go-to for quick prototypes — wired up ESP32 wireless, sensor readings, and relay control to validate hardware ideas fast.","projects":["Wireless Whack-a-Mole"]},{"name":"MATLAB","level":"基礎","desc":"Used for signal processing analysis and quick algorithm checks — plotting things out to sanity-check filter behavior and model logic before writing the real implementation.","projects":[]}]},"eda":{"title":"Electronic Design","en":"Electronic Design Automation","overview":"I''ve done the full flow from schematic to PCB layout with Altium, EasyEDA Pro, and KiCAD — most comfortable with power management and MCU peripheral circuits.","skills":[{"name":"Altium Designer","level":"進階","desc":"My main tool for multi-layer PCB design — power planning, impedance matching, DFM principles, all the way from schematic to Gerber output, on my own.","projects":["QMK × STM32 Custom Numpad"]},{"name":"EasyEDA Pro (LCEDA)","level":"熟悉","desc":"A browser-based EDA tool hooked into the LCSC parts library — footprints are ready to use and you can order a prototype in one click. Used it for the QMK numpad PCB, from schematic to layout to Gerber export.","projects":["QMK × STM32 Custom Numpad"]},{"name":"KiCAD","level":"熟悉","desc":"Open-source EDA I reach for on personal projects when I need a board fast — comfortable with library management and 3D footprint preview, good for early-stage concept checks.","projects":[]},{"name":"OrCAD","level":"基礎","desc":"Basic schematic drawing and SPICE simulation — used it to check passive component choices and power circuit behavior.","projects":[]}]},"manufacturing":{"title":"Manufacturing","en":"Manufacturing","overview":"From design to physical parts — CNC milling, 3D printing, metal welding, laser cutting. Modeling in Inventor, toolpaths in Mastercam.","skills":[{"name":"CNC Milling","level":"基礎","desc":"Precision aluminum machining on CNC mills — I plan toolpaths and design fixtures myself, and it''s noticeably more accurate and repeatable than manual milling.","projects":["FRC Swerve Drive Research"]},{"name":"Mastercam","level":"基礎","desc":"CAM software for CNC — import a 3D model, plan toolpaths (drilling, 2D/3D pocketing, contour milling, dynamic milling, chamfering), simulate it, then output the NC program. Used it for the Swerve Drive''s aluminum wheel plates and drive shafts.","projects":["FRC Swerve Drive Research"]},{"name":"3D Printing","level":"進階","desc":"FDM printing for checking mechanical interference and making custom non-structural parts — cuts weight and machining cost without touching structural integrity.","projects":["FRC Swerve Drive Research","Wireless Whack-a-Mole"]},{"name":"Autodesk Inventor","level":"進階","desc":"My main tool for 3D mechanism modeling — assembly interference checks and dynamic simulation to catch part collisions and tolerance issues before anything gets built.","projects":["FRC Swerve Drive Research"]},{"name":"AutoCAD","level":"進階","desc":"2D engineering drawings for machining — dimensions and tolerances spelled out clearly enough for CNC operators or outside vendors to just follow.","projects":["FRC Swerve Drive Research"]},{"name":"Fusion 360","level":"熟悉","desc":"Quick concept modeling with built-in CAM — good for early design exploration, and you can go straight from the 3D model to a machining path for small-batch parts.","projects":[]},{"name":"Metal Welding","level":"基礎","desc":"Basic MIG/TIG welding for the FRC robot''s steel tube chassis — paying attention to bead uniformity and structural strength.","projects":["FRC Swerve Drive Research"]},{"name":"Laser Cutting","level":"進階","desc":"Precision cutting of sheet metal and acrylic from CAD drawings — a quick way to make custom thin-plate parts and label panels.","projects":[]},{"name":"Basic Machining","level":"熟悉","desc":"Manual mill and lathe basics — measuring tools, workpiece clamping — the groundwork that made picking up advanced CNC machining easier.","projects":[]}]}}',
    updated_at = datetime('now')
WHERE key = 'skills_detail';

UPDATE projects
SET zh = '{"id":"vap","featured":true,"cover":"/images/vap/cover-ai.jpg","category":"大學專題作品","title":"ICU VAP 早期預測：試驗性方法論驗證研究","period":"2025 – 現在","description":"單中心試驗性方法論驗證（亞東紀念醫院 ICU，n=107）。以 Integrated Gradients 消除數學共線冗餘特徵（mv_total，mv≡Vt×RR），從 14 項篩選至 4 項非侵入指標。論文獲 IEEE GCCE 2026 接受（poster）；接受後自行複查評估設定，發現原本的視窗層切分讓同一病人的時間窗橫跨訓練/測試集，改以病人層切分重跑後 AUROC 為 0.61–0.67。研究定位：試驗性方法論驗證，非臨床部署產品。","badge":"IEEE GCCE 2026 · Poster","tags":["LSTM · Time-Series","Integrated Gradients","Stay-Level CV","SMOTE","Medical AI"],"detail":{"images":[{"src":"/images/vap/fig-pipeline.png","caption":"系統流程：特徵篩選 → 滑動視窗 → LSTM → 多時程評估"},{"src":"/images/vap/fig-lstm-vs-baseline.png","caption":"Fig. 1　LSTM vs 傳統 ML 基準（AUROC / AUPRC / Sensitivity / Specificity）"},{"src":"/images/vap/fig-lstm-performance.png","caption":"Fig. 2　LSTM 4-feat 各預警時程效能（6–72 h）"}],"purpose":"VAP 發生率約 5–15%（機械通氣病患），死亡率 20–50%，臨床診斷通常滯後 48 小時以上；現行方法依賴定期評估，無法利用連續監測訊號的時序趨勢。\n\n本研究以亞東紀念醫院 ICU 2019–2023 年資料（n=107：VAP 52 例、非 VAP 55 例），建立 LSTM 時序分類管線，以 4 項常規生命徵象（MAP、呼吸速率、潮氣容積、SpO₂）提前 6–72 小時預警 VAP。\n\n模型選擇：LSTM vs GRU / Transformer\nVAP 生理變化呈連續時序漂移（感染前 48–72 小時可見），靜態特徵不足以捕捉長程依賴。LSTM cell state 在 72 小時窗口下梯度穩定性優於 GRU；Transformer 在 n=107 小樣本下過擬合，對比測試均不及 LSTM。最終確立 LSTM 為主模型。（與 LR、RF、SVM 的比較是在視窗層切分下做的，複查後未重跑，不作為效能主張。）\n\n【研究侷限與誠實邊界】\n本研究是試驗性方法論驗證，非臨床可部署系統。三項核心限制：(1) 單中心資料（亞東紀念醫院），泛化至其他 ICU 族群的能力尚未建立。(2) 小樣本（n=107）——改以病人層切分後 AUROC 僅 0.61–0.67，這組資料不足以支撐部署級臨床效能的主張。(3) 在考慮任何臨床應用前，需於多中心、更大樣本的資料集上完成外部驗證。原先在本地資料上看到的高 AUROC，來自視窗層切分造成的樂觀偏誤，不是模型的真實泛化能力。","concept":"【一、論文復刻與資料洩漏發現】\n以 PREDICT 論文（JCM 2025）為基礎，使用 MIMIC-IV 公開資料集完整復刻其 LSTM 三層架構。復刻過程中發現原論文採用 Window-level Cross Validation——同一病患的時間窗口同時出現在訓練與測試集，造成 AUROC 虛高至 0.99，屬 Data Leakage。此發現為本研究的核心貢獻之一。\n\n【二、正確驗證方法建立】\n將切割方式改為 Stay-level Cross Validation（以病患為單位切分），消除洩漏後於 MIMIC-IV 上得到真實效能（AUROC ≈ 0.58），驗證了論文結果的侷限性。隨後以亞東紀念醫院 ICU 資料（2019–2023 年，有效樣本 107 人：VAP 52 例、非 VAP 55 例；VAP 組入院 APACHE II 顯著較高：25.9 vs 20.1，p＜0.001）進行本地訓練；各折僅在訓練集內套用 SMOTE（1:10），確保過採樣不跨越訓練 / 測試邊界。\n\n【三、特徵工程與可解釋性】\n對 14 個生理與通氣特徵進行 Integrated Gradients（IG）歸因分析，篩選出最具預測力的 Top 4 特徵：MAP（平均動脈壓）、Vent Rate（呼吸器設定頻率）、Tidal Volume（潮氣容積）、SpO₂（血氧飽和度）。進一步透過 Ablation Study 驗證各特徵不可取代性。\n\n【四、技術架構】\n・模型：LSTM × 3 層（各 50 units）+ Dropout，二元分類輸出\n  ─ 深度選擇依據：2 層在長窗口（72 h）下梯度消失明顯；4 層在小樣本下過擬合，3 層為最佳平衡點\n・輸入：24 小時滑動視窗 × 4 特徵，逐小時滑動\n・框架：TensorFlow / Keras + GPU（NVIDIA RTX 4080 Laptop）\n・可解釋性：Integrated Gradients（積分梯度法）\n・對比基準：Logistic Regression、Random Forest、SVM（同設定公平比較）","outcome":"【模型效能：兩種切分方式的對照】\n\n原始評估採視窗層（window-level）切分，同一病人的時間窗會同時落在訓練與測試集，屬過度理想化的條件。論文接受後自行複查，改以病人層（stay-level）切分重跑：\n\n預警時間　　　視窗層 AUROC / AUPRC　病人層 AUROC / AUPRC\n提前  6 小時　0.980 / 0.814　　　　0.646 / 0.033\n提前 12 小時　—　　　　　　　　　　0.674 / 0.054\n提前 24 小時　0.992 / 0.933　　　　0.675 / 0.071\n提前 48 小時　—　　　　　　　　　　0.625 / 0.106\n提前 72 小時　0.987 / 0.921　　　　0.614 / 0.143\n\n右欄為 2026-07-13 的複查結果；其中只有 72 小時窗口跑滿 5 fold，其餘窗口的第 5 折未完成。會議審稿人亦獨立就評估設定提出同一疑問（每個病人產生多少時間窗、AUROC 是以病人還是以視窗為單位計算），與自行複查的結論一致。\n\n【核心特徵（Top 4，IG 分析）】\n・MAP（平均動脈壓）\n・Vent Rate（呼吸器設定頻率）\n・Tidal Volume（潮氣容積）\n・SpO₂（血氧飽和度）\n\n【研究貢獻】\n・在自己的論文裡找出評估洩漏：重建資料切分索引，確認原始數字來自視窗層切分的樂觀偏誤\n・台灣本土化資料：以台灣 ICU 真實資料建立的 VAP 預測管線\n・輕量化特徵組合：僅 4 個常規監測指標，無需額外侵入性檢查\n・臨床可解釋性：IG 分析呈現模型判斷依據\n\n【消融實驗：mv_total 排除驗證】\nmv_total（分鐘通氣量）IG 歸因排名第一（0.00989），但因 mv≡Vt×RR 為數學冗餘特徵，移除後 24 小時 AUROC 反升 +0.004、AUPRC 升 +0.014，確認冗餘特徵應以模型行為驗證，而非單憑歸因分數決定取捨。（此消融同樣在視窗層切分下取得，複查後未重跑。）\n\n📄 論文題目：基於 Stay-Level 交叉驗證與延長預測窗口之 LSTM 呼吸器相關肺炎早期預測研究\n論文完稿 2026.05，獲 IEEE GCCE 2026 接受（poster），會場神戶。","tech":[{"group":"深度學習","items":[{"name":"LSTM 時序建模","desc":"獨立設計 3 層 LSTM（各 50 units）+ Dropout 架構，掌握時序窗口切割、Dropout 正則化與超參數調整；以 TensorFlow / Keras 實作完整訓練迴圈"},{"name":"類別不平衡處理","desc":"各折訓練集內套用 SMOTE（1:10），理解過採樣必須在切分後執行的 Data Leakage 邊界；資料集整體近乎平衡（52 VAP：55 非 VAP），但各折訓練子集比例仍有波動，SMOTE 確保每折訓練穩定"},{"name":"可解釋 AI（XAI）","desc":"以 Integrated Gradients 歸因各特徵對每筆預測的貢獻，進而設計 Ablation Study 驗證 Top 4 特徵的不可取代性"}]},{"group":"實驗設計","items":[{"name":"防洩漏驗證設計","desc":"自行設計 Stay-level CV（以病患為單位切分），解決原論文 Window-level CV 造成同一病患橫跨訓練/測試集的 Data Leakage；於 MIMIC-IV 復刻實驗中，AUROC 從虛高 0.99 降至真實 0.58。亞東資料的主實驗起初仍沿用視窗層切分，論文接受後自行複查才發現並改正，AUROC 由 0.98–0.99 降至 0.61–0.67（詳見研究成果）"},{"name":"Per-fold 正規化","desc":"每折獨立計算 mean/std 後再正規化，避免測試集統計量滲漏進訓練過程，掌握正規化與切分順序的嚴謹性邊界"},{"name":"Ablation Study","desc":"移除 IG 排名第一的 mv_total（mv≡Vt×RR 數學冗餘），24h AUROC 反升 +0.004、AUPRC 升 +0.014，驗證特徵重要度應以模型行為而非歸因分數單一判斷；Cdyn（第11名）與 ΔP（第13名）歸因偏低一併排除"}]},{"group":"特徵工程","items":[{"name":"滑動視窗建構","desc":"以 24 小時固定長度逐小時滑動，處理不等長 ICU 時序記錄的窗口對齊與邊界截斷問題"},{"name":"生理訊號前處理","desc":"帶通濾波、Z-score 標準化、缺失值插補，確保連續監測資料輸入品質；以 pandas / NumPy 實作 ETL 管線"}]}],"github":""}}',
    en = '{"id":"vap","featured":true,"cover":"/images/vap/cover-ai.jpg","category":"大學專題作品","title":"ICU VAP Prediction: Pilot Methodology Validation","period":"2025 – Present","description":"Pilot methodology validation on a single-center ICU dataset (Far Eastern Memorial Hospital, n=107). Integrated Gradients eliminated co-linear redundancy (mv_total where mv≡Vt×RR), distilling 14 features to 4 non-invasive metrics. Accepted to IEEE GCCE 2026 (poster); a self-audit after acceptance found that window-level splitting placed time windows from the same patient on both sides of the split, and re-running with patient-level splits gave AUROC 0.61–0.67. Scope: single-center pilot — methodology validation, not a clinical deployment product.","badge":"IEEE GCCE 2026 · Poster","tags":["LSTM · Time-Series","Integrated Gradients","Stay-Level CV","SMOTE","Medical AI"],"detail":{"images":[{"src":"/images/vap/fig-pipeline.png","caption":"Pipeline: feature selection → sliding window → LSTM → multi-horizon evaluation"},{"src":"/images/vap/fig-lstm-vs-baseline.png","caption":"Fig. 1  LSTM vs. traditional ML baselines (AUROC / AUPRC / Sensitivity / Specificity)"},{"src":"/images/vap/fig-lstm-performance.png","caption":"Fig. 2  LSTM 4-feat performance across warning horizons (6–72 h)"}],"purpose":"VAP incidence is ~5–15% in mechanically ventilated patients with 20–50% mortality, and clinical diagnosis typically lags 48+ hours behind onset. Current methods rely on periodic assessment and cannot leverage the temporal trends available from continuous monitoring.\n\nUsing Far Eastern Memorial Hospital ICU data (2019–2023, n=107: VAP 54, non-VAP 55), we built an LSTM time-series classification pipeline using 4 routine vital signs (MAP, respiratory rate, tidal volume, SpO₂) to provide 6–72 hour early warning of VAP.\n\nModel selection — LSTM vs. GRU/Transformer:\nVAP physiological changes exhibit continuous temporal drift (visible 48–72 hours before infection onset), so static features are insufficient to capture long-range dependencies. LSTM cell state shows better gradient stability than GRU on 72-hour windows; Transformer overfits on the n=107 small dataset. LSTM achieved consistently higher AUROC/AUPRC than LR, RF, and SVM across all windows.\n\n[Study Limitations & Honest Scope]\nThis project is a pilot methodology validation, not a production clinical system. Key constraints: (1) Single-center dataset from Far Eastern Memorial Hospital only — generalizability to other ICU populations is not yet established. (2) Small sample size (n=107) — results demonstrate the effectiveness of Stay-Level CV as a validation methodology; they should not be interpreted as evidence of deployment-ready clinical performance. (3) External validation on a multi-center, larger dataset is required before any clinical deployment consideration. The high AUROC on local data reflects a well-controlled, leakage-free experimental design applied to a small homogeneous cohort.","concept":"[1. Paper Replication & Data Leakage Discovery]\nBased on the PREDICT paper (JCM 2025), we fully replicated its 3-layer LSTM architecture using the MIMIC-IV public dataset. During replication, we discovered that the original paper used Window-level Cross Validation — the same patient''s time windows appeared in both training and test sets, inflating AUROC to 0.99. This data leakage finding is one of the core contributions of this research.\n\n[2. Correct Validation Methodology]\nSwitching to Stay-level Cross Validation (patient-wise splitting) eliminated the leakage and revealed true performance (AUROC ≈ 0.58) on MIMIC-IV, confirming the limitations of the original paper''s results.\n\nFor the local Far Eastern ICU dataset (2019–2023, 110 enrolled, 1 excluded for <72h ventilation, effective n=107: VAP 54, non-VAP 55; VAP group had significantly higher APACHE II on admission: 25.9 vs 20.1, p<0.001), SMOTE (1:10) was applied within each training fold only, ensuring oversampling did not cross train/test boundaries.\n\n[3. Feature Engineering & Interpretability]\n14 physiological and ventilation features were analyzed with Integrated Gradients (IG), yielding the top 4 most predictive features: MAP (mean arterial pressure), Vent Rate (ventilator set rate), Tidal Volume, SpO₂. Ablation studies further validated the indispensability of each.\n\n[4. Technical Architecture]\n- Model: 3-layer LSTM (50 units each) + Dropout, binary classification output\n  (Depth rationale: 2 layers show gradient vanishing on 72h windows; 4 layers overfit on small samples; 3 layers is optimal)\n- Input: 24-hour sliding window × 4 features, sliding by 1 hour\n- Framework: TensorFlow/Keras + GPU (NVIDIA RTX 4080 Laptop)\n- Interpretability: Integrated Gradients\n- Baselines: Logistic Regression, Random Forest, SVM (same settings, fair comparison)","outcome":"[Model Performance — Two Splitting Schemes Compared]\n\nThe original evaluation used window-level splitting, which places time windows from the same patient on both sides of the split — an overly idealized condition. After the paper was accepted, a self-audit re-ran everything with patient-level (stay-level) splits:\n\nHorizon      Window-level AUROC / AUPRC    Stay-level AUROC / AUPRC\n6 hours      0.980 / 0.814                 0.646 / 0.033\n12 hours     —                             0.674 / 0.054\n24 hours     0.992 / 0.933                 0.675 / 0.071\n48 hours     —                             0.625 / 0.106\n72 hours     0.987 / 0.921                 0.614 / 0.143\n\nThe right-hand column is the 2026-07-13 re-audit; only the 72-hour window completed all 5 folds. A conference reviewer independently raised the same question about the evaluation setup (how many windows each patient contributes, and whether AUROC is computed per patient or per window), matching the finding from the self-audit.\n\n[Core Features — Top 4, IG Analysis]\n- MAP (Mean Arterial Pressure)\n- Vent Rate (Ventilator Set Rate)\n- Tidal Volume\n- SpO₂ (Oxygen Saturation)\n\n[Research Contributions]\n- Found an evaluation leak in my own paper: rebuilt the data-split indices and confirmed the original figures came from window-level splitting\n- Taiwan-localized data: a VAP prediction pipeline built on real Taiwan ICU data\n- Lightweight feature set: only 4 routine monitoring indicators, no invasive procedures\n- Clinical interpretability: IG analysis surfaces model reasoning\n\n[Ablation Study: mv_total exclusion]\nmv_total (minute ventilation) ranked #1 in IG attribution (0.00989) but is mathematically redundant (mv≡Vt×RR). Removing it improved 24h AUROC by +0.004 and AUPRC by +0.014, confirming that feature importance should be validated by model behavior, not attribution scores alone. (This ablation was also run under window-level splitting and has not been re-run.)\n\n📄 Paper: \"LSTM-Based Early Prediction of Ventilator-Associated Pneumonia Using Stay-Level Cross-Validation and Extended Prediction Windows\"\nCompleted 2026.05; accepted to IEEE GCCE 2026 (poster), Kobe.","tech":[{"group":"Deep Learning","items":[{"name":"LSTM Time-Series Modeling","desc":"Independently designed 3-layer LSTM (50 units each) + Dropout; implemented complete TensorFlow/Keras training loop with sliding window design, dropout regularization, and hyperparameter tuning"},{"name":"Class Imbalance Handling","desc":"SMOTE (1:10) applied within each training fold; understanding that oversampling must be performed after splitting to prevent data leakage across boundaries"},{"name":"Explainable AI (XAI)","desc":"Integrated Gradients to attribute each feature''s contribution per prediction, combined with ablation studies to validate the indispensability of the Top 4 features"}]},{"group":"Experimental Design","items":[{"name":"Leakage-Free Validation","desc":"Self-designed Stay-level CV (patient-wise splits) to address window-level CV leakage in the original paper; in a MIMIC-IV replication, AUROC dropped from an inflated 0.99 to a true 0.58. The main FEMH experiment, however, still used window-level splitting at first; a self-audit after the paper was accepted caught this, and AUROC fell from 0.98-0.99 to 0.61-0.67 (see Results)"},{"name":"Per-fold Normalization","desc":"Independent mean/std computed per fold before normalization, preventing test set statistics from contaminating training — mastering the strict ordering of normalization and splitting"},{"name":"Ablation Study","desc":"Removing IG-top-ranked mv_total (mathematically redundant: mv≡Vt×RR) improved 24h AUROC +0.004 and AUPRC +0.014, validating that model behavior — not attribution scores alone — should determine feature selection"}]},{"group":"Feature Engineering","items":[{"name":"Sliding Window Construction","desc":"Fixed 24-hour windows sliding hourly, handling variable-length ICU time-series with window alignment and boundary truncation"},{"name":"Physiological Signal Preprocessing","desc":"Band-pass filtering, Z-score normalization, missing-value imputation for continuous monitoring data quality; ETL pipeline implemented with pandas/NumPy"}]}],"github":""}}',
    updated_at = datetime('now')
WHERE id = 'vap';
